#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<int>a(n);
unordered_map<int,int>c;
for(int i=0;i<n;++i){scanf("%d",&a[i]);++c[a[i]];}
sort(a.begin(),a.end(),[&](int x,int y){
if(c[x]!=c[y])return c[x]<c[y];
return x>y;});
for(int i=0;i<n;++i){if(i)printf(" ");printf("%d",a[i]);}
printf("\n");return 0;}

